-- PT124-S2-Q7. Batch 05.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT124-S2-Q7$batch05$ AND q.stimulus=$batch05$In Western economies, more energy is used to operate buildings than to operate transportation. Much of the decline in energy consumption since the oil crisis of 1973 is due to more efficient use of energy in homes and offices. New building technologies, which make lighting, heating, and ventilation systems more efficient, have cut billions of dollars from energy bills in the West. Since energy savings from these efficiencies save several billion dollars per year today, we can conclude that 50 to 100 years from now they will save more than $200 billion per year (calculated in current dollars).$batch05$ AND q.prompt=$batch05$On which one of the following assumptions does the argument rely?$batch05$ AND q.correct_choice=$batch05$A$batch05$) THEN RAISE EXCEPTION 'Question changed: PT124-S2-Q7'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch05$PT124-S2-Q7$batch05$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT124-S2-Q7'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT124-S2-Q7$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$In 50 to 100 years, these efficiencies will save more than $200 billion a year.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$Building efficiencies save several billion dollars a year now and have cut billions from Western energy bills.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$This is a prediction, and predictions assume the road ahead stays open. "Several billion now" becomes "over $200 billion later" only if people keep using these technologies. What could stop them? The technology could become too expensive to use, or be abandoned. The answer will rule out something like that.$batch05$), (3, $batch05$Goal$batch05$, $batch05$A defender: nothing will stop people from keeping and expanding these efficiencies, such as the technology becoming too expensive.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT124-S2-Q7$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$Negate it: "the technology *will* become prohibitively expensive." Then buildings stop using it, the savings shrink instead of growing, and $200 billion a year is out of reach.$batch05$), ($batch05$B$batch05$, $batch05$Another oil crisis might raise prices, but the argument does not need one.$batch05$), ($batch05$C$batch05$, $batch05$If buildings become a smaller share of energy use, savings from buildings would matter less. The author would not assume that.$batch05$), ($batch05$D$batch05$, $batch05$This restates the conclusion in different words. An assumption is something the argument relies on to get to the conclusion, not the conclusion itself.$batch05$), ($batch05$E$batch05$, $batch05$This is the most popular wrong answer, and it feels right: how else would savings grow so much? But growth can come from using today's technology in more buildings. The argument does not need brand-new science. Negate E and the prediction can still come true.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT124-S2-Q7$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
